#!/usr/bin/env -S dotnet run

using System.Text.Json;
using System.Text.Json.Nodes;

if (!OperatingSystem.IsLinux())
{
    throw new PlatformNotSupportedException("This setup script is intended for the Linux devcontainer.");
}

var user = RequireEnvironmentVariable("FLYWAY_USER");
var password = RequireEnvironmentVariable("FLYWAY_PASSWORD");
var host = Environment.GetEnvironmentVariable("PGHOST") ?? "localhost";
var port = Environment.GetEnvironmentVariable("PGPORT") ?? "5432";
var settingsPath = Path.GetFullPath(".vscode/settings.json");
var settings = File.Exists(settingsPath)
    ? JsonNode.Parse(await File.ReadAllTextAsync(settingsPath),
        documentOptions: new JsonDocumentOptions
        {
            CommentHandling = JsonCommentHandling.Skip,
            AllowTrailingCommas = true
        })?.AsObject() ?? throw new InvalidOperationException("VS Code settings must be a JSON object.")
    : new JsonObject();

var connections = settings["pgsql.connections"]?.AsArray() ?? new JsonArray();
settings["pgsql.connections"] = connections;

var groups = settings["pgsql.serverGroups"]?.AsArray() ?? new JsonArray();
settings["pgsql.serverGroups"] = groups;
const string generatedGroupId = "276c7d82-371a-48a6-b4bf-21325bca1294";
var defaultGroup = groups.FirstOrDefault(group => group?["isDefault"]?.GetValue<bool>() == true)
    ?? groups.FirstOrDefault(group => group?["id"]?.GetValue<string>() == generatedGroupId);
if (defaultGroup is null)
{
    defaultGroup = new JsonObject
    {
        ["id"] = generatedGroupId,
        ["name"] = "Servers",
        ["isDefault"] = true
    };
    groups.Add(defaultGroup);
}
else if (defaultGroup["id"]?.GetValue<string>() == generatedGroupId)
{
    defaultGroup["name"] = "Servers";
    defaultGroup["isDefault"] = true;
}

var groupId = defaultGroup["id"]?.GetValue<string>()
    ?? throw new InvalidOperationException("The default PostgreSQL server group must have an ID.");

// Remove only the development/test profiles generated by the previous setup.
for (var index = connections.Count - 1; index >= 0; index--)
{
    var id = connections[index]?["id"]?.GetValue<string>();
    if (id is "9ecb8d12-cd42-4198-b3ba-af1b5f25e5a7" or "f7e13f26-f42f-4611-8cef-664bb072d0e8")
    {
        connections.RemoveAt(index);
    }
}

ConfigureProfile("b52cb760-dada-4f44-ab2f-5982ee2f2af3", "RLS Local PostgreSQL", "postgres");

Directory.CreateDirectory(Path.GetDirectoryName(settingsPath)!);
var temporaryPath = $"{settingsPath}.{Guid.NewGuid():N}.tmp";
try
{
    // Profiles contain local development passwords; create the file with owner-only access.
    await using (var stream = new FileStream(temporaryPath, new FileStreamOptions
    {
        Mode = FileMode.CreateNew,
        Access = FileAccess.Write,
        UnixCreateMode = UnixFileMode.UserRead | UnixFileMode.UserWrite
    }))
    {
        await using var writer = new Utf8JsonWriter(stream, new JsonWriterOptions { Indented = true });
        settings.WriteTo(writer);
        await writer.FlushAsync();
    }

    File.Move(temporaryPath, settingsPath, overwrite: true);
}
finally
{
    if (File.Exists(temporaryPath))
    {
        File.Delete(temporaryPath);
    }
}

Console.WriteLine("Configured the RLS local PostgreSQL profile in local VS Code settings.");

void ConfigureProfile(string id, string name, string database)
{
    JsonNode profile = new JsonObject
    {
        ["id"] = id,
        ["groupId"] = groupId,
        ["profileName"] = name,
        ["server"] = host,
        ["port"] = port,
        ["database"] = database,
        ["authenticationType"] = "SqlLogin",
        ["user"] = user,
        ["password"] = password,
        ["savePassword"] = true,
        ["sslmode"] = "disable"
    };
    for (var index = 0; index < connections.Count; index++)
    {
        if (connections[index]?["id"]?.GetValue<string>() == id)
        {
            connections[index] = profile;
            return;
        }
    }

    connections.Add(profile);
}

static string RequireEnvironmentVariable(string name)
{
    var value = Environment.GetEnvironmentVariable(name);
    if (string.IsNullOrWhiteSpace(value))
    {
        throw new InvalidOperationException($"Set the {name} environment variable.");
    }

    return value;
}
